<script>
(()=>{'use strict';const root=document.querySelector('[data-nc]');if(!root)return;root.__ncCleanup?.();const reduced=matchMedia('(prefers-reduced-motion: reduce)'),animations=new Set();let observer;
function stop(){animations.forEach(a=>a.cancel());animations.clear();}
function reveal(el){if(reduced.matches||typeof el.animate!=='function')return;const a=el.animate([{opacity:0,translate:'0 14px'},{opacity:1,translate:'0 0'}],{duration:650,easing:'cubic-bezier(.16,1,.3,1)'});animations.add(a);a.onfinish=a.oncancel=()=>animations.delete(a);}
reduced.addEventListener('change',stop);if(typeof IntersectionObserver==='function'){observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){reveal(e.target);observer.unobserve(e.target);}}),{threshold:.15});root.querySelectorAll('.nc-copy,.nc-role,.nc-login').forEach(el=>observer.observe(el));}
root.__ncCleanup=()=>{observer?.disconnect();stop();reduced.removeEventListener('change',stop);delete root.__ncCleanup;};})();
</script>
